namespace Hospital.Domain.Entities;
/// <summary>
/// Represents a scheduled appointment between a patient and a doctor.
/// </summary>
public class Appointment
{
    /// <summary>
    /// Primary key (auto-generated by database).
    /// </summary>
    public int Id { get; set; }

    /// <summary>
    /// Date and time when the appointment starts.
    /// </summary>
    public DateTime? StartAt { get; set; }

    /// <summary>
    /// Room number where the appointment takes place.
    /// </summary>
    public string? RoomNumber { get; set; }

    /// <summary>
    /// True if this appointment is a follow-up, false otherwise.
    /// </summary>
    public bool IsFollowUp { get; set; }

    /// <summary>
    /// Gets or sets the foreign key of the patient associated with this appointment.
    /// </summary>
    public int PatientId { get; set; }

    /// <summary>
    /// Navigation property to the patient.
    /// </summary>
    public Patient? Patient { get; set; }

    /// <summary>
    /// Gets or sets the foreign key of the doctor associated with this appointment.
    /// </summary>
    public int DoctorId { get; set; }

    /// <summary>
    /// Navigation property to the doctor.
    /// </summary>
    public Doctor? Doctor { get; set; }
}